CREATE TABLE IF NOT EXISTS user_mfa (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, secret_ciphertext text NOT NULL, enabled boolean NOT NULL DEFAULT false, last_totp_step bigint NOT NULL DEFAULT -1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS auth_mfa_challenges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0 AND attempts <= 5), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_auth_mfa_challenges_expiry ON auth_mfa_challenges(expires_at);
CREATE TABLE IF NOT EXISTS user_mfa_recovery_codes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, code_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,code_hash));
